pub fn decode_method(node: &Node) -> Result<Method, DecodeError> {
    let mut parts = support::call_of(
        node,
        &[
            "the call `_? METHOD _ RETURNS _`",
            "the call `_? METHOD _ RETURNS NOTHING`",
        ],
    )?;
    let decoded = Method {
        doc: parts.optional(|node| support::line_string(node, |_| true, "a `#` line string")),
        read_only: if parts
            .choose(&["READ"], false, true, &["the word `READ ONLY`"])?
            .is_some()
        {
            Some(parts.word_span("READ ONLY")?)
        } else {
            None
        },
        idempotent: if parts
            .choose(&["IDEMPOTENT"], false, true, &["the word `IDEMPOTENT`"])?
            .is_some()
        {
            Some(parts.word_span("IDEMPOTENT")?)
        } else {
            None
        },
        shape: parts.word("METHOD")?.one(decode_shape, "a shape")?,
        requires: if parts
            .choose(&["REQUIRES"], false, true, &["the word `REQUIRES`"])?
            .is_some()
        {
            Some(
                parts
                    .word("REQUIRES")?
                    .one(decode_condition, "a condition")?,
            )
        } else {
            None
        },
        returns: {
            parts.word("RETURNS")?;
            match parts.choose(
                &["NOTHING"],
                true,
                false,
                &["returns", "the word `NOTHING`"],
            )? {
                Some(0) => MethodReturns::Nothing(parts.word_span("NOTHING")?),
                _ => MethodReturns::Value(parts.one(decode_returns, "returns")?),
            }
        },
        ensures: if parts
            .choose(&["ENSURES"], false, true, &["the word `ENSURES`"])?
            .is_some()
        {
            Some(
                parts
                    .word("ENSURES")?
                    .one(decode_condition, "a condition")?,
            )
        } else {
            None
        },
        errors: if parts
            .choose(&["ERRORS"], false, true, &["the word `ERRORS`"])?
            .is_some()
        {
            Some(
                parts
                    .word("ERRORS")?
                    .one(decode_error_list, "an error list")?,
            )
        } else {
            None
        },
        undone_by: if parts
            .choose(&["UNDONE"], false, true, &["the word `UNDONE`"])?
            .is_some()
        {
            Some(
                parts
                    .word("UNDONE")?
                    .word("BY")?
                    .one(decode_undo, "an undo")?,
            )
        } else {
            None
        },
        examples: if parts
            .choose(&["EXAMPLES"], false, true, &["the word `EXAMPLES`"])?
            .is_some()
        {
            Some(parts.word("EXAMPLES")?.one(decode_examples, "examples")?)
        } else {
            None
        },
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

