pub fn decode_error_term(node: &Node) -> Result<ErrorTerm, DecodeError> {
    decode_error_term_own(node)
        .map(ErrorTerm::Own)
        .or_else(|error| error.or(decode_error_term_call(node)))
}

fn decode_error_term_own(node: &Node) -> Result<Spanned<Vec<Error>>, DecodeError> {
    let mut elements = support::square_bracket(node)?;
    let value = elements.one_or_more(decode_error, "an error")?;
    elements.finish()?;
    Ok(Spanned {
        value,
        span: node.span,
    })
}

fn decode_error_term_call(node: &Node) -> Result<ErrorTerm, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword),
        "a call whose name has no keyword",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = ErrorTerm::Call {
        name,
        arguments: arguments.zero_or_more(decode_error_term),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_error(node: &Node) -> Result<Error, DecodeError> {
    decode_variant(node)
}

pub fn decode_shape(node: &Node) -> Result<Shape, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword),
        "a call whose name has no keyword",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = Shape {
        name,
        arguments: arguments.zero_or_more(decode_parameter),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_parameter(node: &Node) -> Result<Parameter, DecodeError> {
    let mut parts = support::call(node, "the call `… _`")?;
    let decoded = Parameter {
        name: parts.words(
            |text| !text.split(' ').any(anyx::is_keyword),
            "words whose text has no keyword",
        )?,
        r#type: parts.one(decode_type, "a type")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

pub fn decode_type(node: &Node) -> Result<Type, DecodeError> {
    decode_refined_type(node)
        .map(Type::Refined)
        .or_else(|error| error.or(decode_list_type(node).map(Type::List)))
        .or_else(|error| error.or(decode_map_type(node).map(Type::Map)))
        .or_else(|error| error.or(decode_union_type(node).map(Type::Union)))
        .or_else(|error| error.or(decode_reference(node).map(Type::Named)))
}

pub fn decode_refined_type(node: &Node) -> Result<RefinedType, DecodeError> {
    let mut parts = support::call(node, "the call `_ WHERE _`")?;
    let decoded = RefinedType {
        base: parts.one(|node| decode_type(node).map(Box::new), "a type")?,
        predicate: parts
            .word("WHERE")?
            .one(decode_refined_type_predicate, "`[...]`")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

fn decode_refined_type_predicate(node: &Node) -> Result<Spanned<Vec<Term>>, DecodeError> {
    let mut elements = support::square_bracket(node)?;
    let value = elements.one_or_more(decode_term, "a term")?;
    elements.finish()?;
    Ok(Spanned {
        value,
        span: node.span,
    })
}

pub fn decode_term(node: &Node) -> Result<Term, DecodeError> {
    support::underscore(node)
        .map(Term::Subject)
        .or_else(|error| {
            error.or(support::float(
                node,
                f64::NEG_INFINITY,
                f64::INFINITY,
                false,
                "an integer literal",
            )
            .and_then(|_| support::number_literal(node, false, "an integer literal"))
            .map(Term::Integer))
        })
        .or_else(|error| {
            error.or(support::float(
                node,
                f64::NEG_INFINITY,
                f64::INFINITY,
                false,
                "a float literal",
            )
            .and_then(|_| support::number_literal(node, true, "a float literal"))
            .map(Term::Float))
        })
        .or_else(|error| error.or(support::string(node, |_| true, "a string").map(Term::Text)))
        .or_else(|error| error.or(decode_term_variants(node).map(Term::Variants)))
        .or_else(|error| error.or(decode_term_variant(node).map(Term::Variant)))
        .or_else(|error| error.or(decode_term_call(node)))
}

fn decode_term_variants(node: &Node) -> Result<Spanned<Vec<TermVariant>>, DecodeError> {
    let mut elements = support::square_bracket(node)?;
    let value = elements.zero_or_more(decode_term_variant);
    elements.finish()?;
    Ok(Spanned {
        value,
        span: node.span,
    })
}

fn decode_term_call(node: &Node) -> Result<Term, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword) && REGEX_2.is_match(name),
        "a call whose name has no keyword and matches the regex `` ^[^`] ``",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = Term::Call {
        name,
        arguments: arguments.zero_or_more(decode_term),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_term_variant(node: &Node) -> Result<TermVariant, DecodeError> {
    let mut parts = support::call(node, "the call `` ` _ ``")?;
    let decoded = TermVariant {
        body: parts
            .word("`")?
            .one(decode_term_variant_body, "a call whose name has no keyword")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

fn decode_term_variant_body(node: &Node) -> Result<TermVariantBody, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword),
        "a call whose name has no keyword",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = TermVariantBody {
        name,
        arguments: arguments.zero_or_more(support::underscore),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_list_type(node: &Node) -> Result<ListType, DecodeError> {
    let mut parts = support::call(node, "the call `LIST _`")?;
    let decoded = ListType {
        item: parts
            .word("LIST")?
            .one(|node| decode_type(node).map(Box::new), "a type")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

pub fn decode_map_type(node: &Node) -> Result<MapType, DecodeError> {
    let mut parts = support::call(node, "the call `MAP _`")?;
    let decoded = MapType {
        value: parts
            .word("MAP")?
            .one(|node| decode_type(node).map(Box::new), "a type")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

pub fn decode_union_type(node: &Node) -> Result<UnionType, DecodeError> {
    let mut parts = support::call(node, "the call `UNION _`")?;
    let decoded = UnionType {
        members: parts
            .word("UNION")?
            .one(decode_union_type_members, "`[...]`")?,
        span: node.span,
    };
    parts.finish()?;
    Ok(decoded)
}

fn decode_union_type_members(node: &Node) -> Result<Spanned<Vec<UnionMember>>, DecodeError> {
    let mut elements = support::square_bracket(node)?;
    let value = elements.zero_or_more(decode_union_member);
    elements.finish()?;
    Ok(Spanned {
        value,
        span: node.span,
    })
}

pub fn decode_union_member(node: &Node) -> Result<UnionMember, DecodeError> {
    decode_variant(node)
        .map(UnionMember::Variant)
        .or_else(|error| error.or(decode_refined_type(node).map(UnionMember::Refined)))
        .or_else(|error| error.or(decode_union_type(node).map(UnionMember::Union)))
        .or_else(|error| error.or(decode_union_member_named(node)))
}

fn decode_union_member_named(node: &Node) -> Result<UnionMember, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword) && REGEX_3.is_match(name),
        "a call whose name has no keyword and matches the regex `` ^(_ )*[^`_] ``",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = UnionMember::Named {
        name,
        arguments: arguments.zero_or_more(decode_member_slot),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_member_slot(node: &Node) -> Result<MemberSlot, DecodeError> {
    support::line_string(node, |_| true, "a `#` line string")
        .map(MemberSlot::Doc)
        .or_else(|error| error.or(decode_type(node).map(MemberSlot::Type)))
}

pub fn decode_reference(node: &Node) -> Result<Reference, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword),
        "a call whose name has no keyword",
    )?;
    let mut arguments = support::arguments(node, arguments);
    let decoded = Reference {
        name,
        arguments: arguments.zero_or_more(decode_type),
        span: node.span,
    };
    arguments.finish()?;
    Ok(decoded)
}

pub fn decode_type_name(node: &Node) -> Result<TypeName, DecodeError> {
    let (name, arguments) = support::any_call(
        node,
        |name| !name.split(' ').any(anyx::is_keyword) && !name.split(' ').any(|word| word == "_"),
        "a call whose name has no keyword and has no `_`",
    )?;
    Ok(TypeName {
        name,
        arguments: arguments.to_vec(),
        span: node.span,
    })
}

/// Parses `source` with anyx and decodes its document.
pub fn parse_document(source: &str) -> support::Parsed<Document> {
    support::parse(source, decode_document)
}

/// What the grammar's `#` line strings say about what may be written,
/// by what errors call it: ``the call `title _` ``, ``the word `yes` ``.
pub const DOCUMENTATION: &[(&str, &str)] = &[];

/// How [`format`] lays out calls, from the grammar's `FORMAT`s.
pub const LAYOUT: &[support::LayoutRule] = &[
    support::LayoutRule {
        words: &["METHOD", "RETURNS"],
        break_before: &[
            "REQUIRES", "RETURNS", "ENSURES", "ERRORS", "UNDONE", "EXAMPLES",
        ],
    },
    support::LayoutRule {
        words: &["FUNCTION", "RETURNS"],
        break_before: &["RETURNS"],
    },
];

/// Formats `source` canonically, laying calls out as the grammar says.
pub fn format(
    source: &str,
) -> std::result::Result<std::string::String, std::vec::Vec<anyx::Error>> {
    support::format(source, LAYOUT)
}

pub mod support {
    //! What every generated decoder needs: spans, errors, and matching a
    //! sequence of nodes. The generator copies this file into its output, so a
    //! generated parser depends only on `anyx` (and on `regex`, when its
    //! grammar uses `MATCHING REGEX`).

    use anyx::{
        FlatWord, LineColumn, NamePart, Node, NodeKind, Span, StringKind, StringLiteral,
        line_column,
    };

    /// A value and where it was written.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Spanned<T> {
        pub value: T,
        pub span: Span,
    }

    impl<T> std::ops::Deref for Spanned<T> {
        type Target = T;

        fn deref(&self) -> &T {
            &self.value
        }
    }

    /// A decoded value that can hold errors: the ones `EACH` keeps in place of
    /// the elements that did not fit, and the ones `ANY ORDER` keeps for the
    /// nodes that fit nothing. Every generated type has it, so a tool such as a
    /// language server can list every error in a document without knowing its
    /// grammar.
    pub trait Errors {
        /// Adds every error inside `self` to `found`, in source order.
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>);

        /// Every error inside `self`, in source order.
        fn all_errors(&self) -> Vec<&DecodeError> {
            let mut found = Vec::new();
            self.errors(&mut found);
            found
        }
    }

    impl Errors for DecodeError {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            found.push(self);
        }
    }

    impl<T: Errors> Errors for Result<T, DecodeError> {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            match self {
                Ok(value) => value.errors(found),
                Err(error) => found.push(error),
            }
        }
    }

    impl<T: Errors> Errors for Vec<T> {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            for value in self {
                value.errors(found);
            }
        }
    }

    impl<T: Errors> Errors for Option<T> {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            if let Some(value) = self {
                value.errors(found);
            }
        }
    }

    impl<T: Errors> Errors for Box<T> {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            (**self).errors(found);
        }
    }

    impl<T: Errors> Errors for Spanned<T> {
        fn errors<'a>(&'a self, found: &mut Vec<&'a DecodeError>) {
            self.value.errors(found);
        }
    }

    macro_rules! no_errors {
    ($($type:ty),*) => {
        $(impl Errors for $type {
            fn errors<'a>(&'a self, _: &mut Vec<&'a DecodeError>) {}
        })*
    };
}

    no_errors!(
        Span,
        Node,
        StringLiteral,
        String,
        CallName,
        u8,
        u16,
        u32,
        u64,
        u128,
        i8,
        i16,
        i32,
        i64,
        i128,
        f64
    );

    /// The name of a call matched by `ANYFIX CALL`: its text, such as
    /// `max size _`, its words and slots, and where its words are.
    #[derive(Clone, Debug, PartialEq)]
    pub struct CallName {
        /// The words with `_` for each slot, joined by spaces.
        pub text: String,
        pub parts: Vec<NamePart>,
        /// From the first word to the last.
        pub span: Span,
    }

    impl CallName {
        /// The words alone, without the slots: `max size _` is `max` and `size`.
        pub fn words(&self) -> impl Iterator<Item = &str> {
            self.parts.iter().filter_map(|part| match part {
                NamePart::Word { text, .. } => Some(text.as_str()),
                NamePart::Slot => None,
            })
        }

        /// The words with the call's `arguments` written out flat in their
        /// slots (see [`Node::flat_words`]), or the first argument that is not
        /// words, numbers and strings.
        pub fn flat_words<'a>(&self, arguments: &'a [Node]) -> Result<Vec<FlatWord>, &'a Node> {
            anyx::flat_words(&self.parts, arguments)
        }
    }

    /// Why a tree does not fit the grammar: what stands at `span`, and what the
    /// grammar allows there.
    #[derive(Clone, Debug, PartialEq, Eq)]
    pub struct DecodeError {
        pub span: Span,
        pub found: String,
        pub expected: Vec<String>,
    }

    impl DecodeError {
        pub fn new(span: Span, found: impl Into<String>, expected: impl Into<String>) -> Self {
            DecodeError {
                span,
                found: found.into(),
                expected: vec![expected.into()],
            }
        }

        /// `found X; expected A, B or C`, in one line. Words are listed
        /// together, and so are calls: ``the word `OF` or `OR` ``.
        pub fn message(&self) -> String {
            let mut expected = Vec::new();
            for kind in ["the word ", "the call "] {
                let same_kind = self
                    .expected
                    .iter()
                    .filter_map(|one| one.strip_prefix(kind));
                for (index, rest) in same_kind.enumerate() {
                    expected.push(match index {
                        0 => format!("{kind}{rest}"),
                        _ => rest.to_string(),
                    });
                }
            }
            let others = self
                .expected
                .iter()
                .filter(|one| !one.starts_with("the word ") && !one.starts_with("the call "));
            expected.extend(others.cloned());
            let expected = match &expected[..] {
                [] => "nothing".to_string(),
                [only] => only.clone(),
                [rest @ .., last] => format!("{} or {last}", rest.join(", ")),
            };
            format!("found {}; expected {expected}", self.found)
        }

        /// Where the error starts in `source`, as a line and column.
        pub fn position(&self, source: &str) -> LineColumn {
            line_column(source, self.span.start)
        }

        /// `file:line:column: message`, then the source line with `^` under the span.
        pub fn render(&self, source: &str, file: &str) -> String {
            let at = self.position(source);
            let line = source.lines().nth(at.line - 1).unwrap_or("");
            let width = source
                .get(self.span.start..self.span.end)
                .map_or(1, |text| text.lines().next().unwrap_or("").chars().count())
                .max(1);
            format!(
                "{file}:{at}: {}\n  {line}\n  {}{}",
                self.message(),
                " ".repeat(at.column - 1),
                "^".repeat(width)
            )
        }

        /// The more useful of two errors about the same input: the one that got
        /// further into the source, and of two starting at the same place, the
        /// one about the smaller part. Errors about the same span are joined,
        /// since every one of their expectations was possible there.
        pub fn merge(mut self, other: DecodeError) -> DecodeError {
            let rank = |error: &DecodeError| (error.span.start, std::cmp::Reverse(error.span.end));
            match rank(&self).cmp(&rank(&other)) {
                std::cmp::Ordering::Less => other,
                std::cmp::Ordering::Greater => self,
                std::cmp::Ordering::Equal => {
                    for expected in other.expected {
                        if !self.expected.contains(&expected) {
                            self.expected.push(expected);
                        }
                    }
                    self
                }
            }
        }

        /// The next choice of a `ONE OF`, tried after this error: its result if
        /// it matches, else both errors merged.
        pub fn or<T>(self, next: Result<T, DecodeError>) -> Result<T, DecodeError> {
            next.map_err(|error| self.merge(error))
        }
    }

    impl std::fmt::Display for DecodeError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            formatter.write_str(&self.message())
        }
    }

    impl std::error::Error for DecodeError {}

    /// How an error names the node it found.
    pub fn describe(node: &Node) -> String {
        match &node.kind {
            NodeKind::Number(text) => format!("the number `{text}`"),
            NodeKind::String(literal) => format!("the string {}", string_value(literal)),
            NodeKind::Call(call) => match &call.name[..] {
                [NamePart::Word { text, .. }] => format!("the word {}", code(text)),
                _ => format!("the call {}", code(&call.name_text())),
            },
            NodeKind::Parens(_) => "`(...)`".to_string(),
            NodeKind::Brackets(_) => "`[...]`".to_string(),
            NodeKind::Braces(_) => "`{...}`".to_string(),
            NodeKind::Underscore => "`_`".to_string(),
            NodeKind::Missing => "nothing".to_string(),
        }
    }

    /// A string's value as an error quotes it, cut short after 40 characters.
    fn string_value(literal: &StringLiteral) -> String {
        let mut value: String = literal.value.chars().take(40).collect();
        if value.len() < literal.value.len() {
            value.push('…');
        }
        format!("{value:?}")
    }

    /// The error for a node that is not what the grammar expects there.
    pub fn mismatch(node: &Node, expected: &str) -> DecodeError {
        DecodeError::new(node.span, describe(node), expected)
    }

    /// A sequence being matched from left to right: the elements of a bracket or
    /// of the document, or the words and arguments of a call.
    pub struct Sequence<'a> {
        items: Vec<Item<'a>>,
        index: usize,
        /// What the end of the sequence is called, and where it is.
        end: (&'static str, Span),
        /// Why the last repetition stopped. When the sequence then fails at the
        /// same place, this is the better explanation.
        missed: Option<DecodeError>,
        /// For a call: the error saying that the whole call is not the expected
        /// one. It is given when a word stands where an argument should, or an
        /// argument where a word should, since the call then has another shape.
        /// Once a word has matched, the call is taken to be the expected one,
        /// and what is wrong with it is said exactly.
        other_call: Option<DecodeError>,
    }

    enum Item<'a> {
        Word(&'a str, Span),
        Node(&'a Node),
    }

    /// A source parsed by anyx and decoded: the syntax errors anyx found and
    /// recovered from, and the document, or why it does not match.
    #[derive(Clone, Debug, PartialEq)]
    pub struct Parsed<T> {
        pub syntax_errors: Vec<anyx::Error>,
        pub document: Result<T, DecodeError>,
    }

    /// Parses `source` with anyx, then decodes its nodes with `decode`.
    pub fn parse<T>(
        source: &str,
        decode: impl FnOnce(&[Node]) -> Result<T, DecodeError>,
    ) -> Parsed<T> {
        let parsed = anyx::parse(source);
        Parsed {
            document: decode(&parsed.syntax.nodes()),
            syntax_errors: parsed.errors,
        }
    }

    /// The sequence of top-level elements of a document.
    pub fn document(nodes: &[Node]) -> Sequence<'_> {
        let end = nodes.last().map_or(0, |last| last.span.end);
        Sequence::new(
            nodes.iter().map(Item::Node).collect(),
            ("the end of the document", Span::empty(end)),
        )
    }

    /// The span of a document: from its first element to its last.
    pub fn document_span(nodes: &[Node]) -> Span {
        match (nodes.first(), nodes.last()) {
            (Some(first), Some(last)) => first.span.to(last.span),
            _ => Span::empty(0),
        }
    }

    /// The elements of `{...}`.
    pub fn curly_brace(node: &Node) -> Result<Sequence<'_>, DecodeError> {
        match &node.kind {
            NodeKind::Braces(nodes) => Ok(Sequence::bracket(node, nodes, "the closing `}`")),
            _ => Err(mismatch(node, "`{...}`")),
        }
    }

    /// The elements of `[...]`.
    pub fn square_bracket(node: &Node) -> Result<Sequence<'_>, DecodeError> {
        match &node.kind {
            NodeKind::Brackets(nodes) => Ok(Sequence::bracket(node, nodes, "the closing `]`")),
            _ => Err(mismatch(node, "`[...]`")),
        }
    }

    /// The elements of `(...)`.
    pub fn parenthesis(node: &Node) -> Result<Sequence<'_>, DecodeError> {
        match &node.kind {
            NodeKind::Parens(nodes) => Ok(Sequence::bracket(node, nodes, "the closing `)`")),
            _ => Err(mismatch(node, "`(...)`")),
        }
    }

    /// The words and arguments of a call, in the order written.
    pub fn call<'a>(node: &'a Node, expected: &str) -> Result<Sequence<'a>, DecodeError> {
        let NodeKind::Call(call) = &node.kind else {
            return Err(mismatch(node, expected));
        };
        let mut arguments = call.arguments.iter();
        let items = call
            .name
            .iter()
            .filter_map(|part| match part {
                NamePart::Word { text, span } => Some(Item::Word(text, *span)),
                NamePart::Slot => arguments.next().map(Item::Node),
            })
            .collect();
        let mut sequence =
            Sequence::new(items, ("the end of the call", Span::empty(node.span.end)));
        sequence.other_call = Some(mismatch(node, expected));
        Ok(sequence)
    }

    /// Like [`call`], for a call that may be written in several ways, each
    /// of `expected`.
    pub fn call_of<'a>(node: &'a Node, expected: &[&str]) -> Result<Sequence<'a>, DecodeError> {
        let other_call = || DecodeError {
            expected: expected.iter().map(|one| one.to_string()).collect(),
            ..mismatch(node, "")
        };
        let mut sequence = call(node, "").map_err(|_| other_call())?;
        sequence.other_call = Some(other_call());
        Ok(sequence)
    }

    /// Any call: its name, such as `list file in _`, and its arguments. The
    /// name's text must pass `condition`.
    pub fn any_call<'a>(
        node: &'a Node,
        condition: impl Fn(&str) -> bool,
        expected: &str,
    ) -> Result<(CallName, &'a [Node]), DecodeError> {
        let NodeKind::Call(call) = &node.kind else {
            return Err(mismatch(node, expected));
        };
        let text = call.name_text();
        if !condition(&text) {
            return Err(mismatch(node, expected));
        }
        let mut words = call.name.iter().filter_map(|part| match part {
            NamePart::Word { span, .. } => Some(*span),
            NamePart::Slot => None,
        });
        let span = match (words.next(), words.next_back()) {
            (Some(first), Some(last)) => first.to(last),
            (Some(only), None) => only,
            _ => node.span,
        };
        let name = CallName {
            text,
            parts: call.name.clone(),
            span,
        };
        Ok((name, &call.arguments))
    }

    /// The arguments of the call `node`, as a sequence.
    pub fn arguments<'a>(node: &Node, arguments: &'a [Node]) -> Sequence<'a> {
        Sequence::new(
            arguments.iter().map(Item::Node).collect(),
            ("the end of the call", Span::empty(node.span.end)),
        )
    }

    impl<'a> Sequence<'a> {
        fn new(items: Vec<Item<'a>>, end: (&'static str, Span)) -> Self {
            Sequence {
                items,
                index: 0,
                end,
                missed: None,
                other_call: None,
            }
        }

        fn bracket(node: &Node, nodes: &'a [Node], closer: &'static str) -> Self {
            let end = node.span.end;
            Sequence::new(
                nodes.iter().map(Item::Node).collect(),
                (closer, Span::new(end.saturating_sub(1), end)),
            )
        }

        /// The error for the item at the front not being `expected`.
        fn unexpected(&mut self, expected: &str) -> DecodeError {
            let error = match self.items.get(self.index) {
                Some(Item::Word(text, span)) => {
                    DecodeError::new(*span, format!("the word {}", code(text)), expected)
                }
                Some(Item::Node(node)) => mismatch(node, expected),
                None => DecodeError::new(self.end.1, self.end.0, expected),
            };
            self.fail(error)
        }

        /// The error for a call whose words and arguments are not arranged as
        /// expected. It replaces why an optional part before them did not fit,
        /// since the call is another shape altogether.
        fn is_other_call(&mut self) -> DecodeError {
            self.missed = None;
            self.other_call.clone().expect("the sequence of a call")
        }

        /// Whether the call may be another shape: not when the item at the
        /// front is a string that an optional part refused, such as a quoted
        /// string where a `#` line string goes. The call then has the expected
        /// shape, a slot where the part goes, and the string is what is wrong.
        fn may_be_other_call(&self) -> bool {
            let refused_string = match (self.items.get(self.index), &self.missed) {
                (Some(Item::Node(node)), Some(missed)) => {
                    matches!(node.kind, NodeKind::String(_)) && missed.span == node.span
                }
                _ => false,
            };
            self.other_call.is_some() && !refused_string
        }

        fn fail(&mut self, error: DecodeError) -> DecodeError {
            match self.missed.take() {
                Some(missed) => missed.merge(error),
                None => error,
            }
        }

        /// Where the sequence has got to, for [`Sequence::span_since`].
        pub fn position(&self) -> usize {
            self.index
        }

        /// The span of the items matched since `start`.
        pub fn span_since(&self, start: usize) -> Span {
            let span = |item: &Item| match item {
                Item::Word(_, span) => *span,
                Item::Node(node) => node.span,
            };
            match (
                self.items.get(start),
                self.index
                    .checked_sub(1)
                    .and_then(|last| self.items.get(last)),
            ) {
                (Some(first), Some(last)) if start < self.index => span(first).to(span(last)),
                _ => Span::empty(self.end.1.start),
            }
        }

        /// Which of several groups of a call's parts stands next, told apart by
        /// their first words: the index of the word next, or, if `slot` and a
        /// node is next, `first_words.len()`. When none is, it is `None` if
        /// the group is `optional`, and an error expecting each of `expected`
        /// if not.
        pub fn choose(
            &mut self,
            first_words: &[&str],
            slot: bool,
            optional: bool,
            expected: &[&str],
        ) -> Result<Option<usize>, DecodeError> {
            let next = self.items.get(self.index);
            let word = first_words.iter().position(|word| match next {
                Some(Item::Word(text, _)) => text == word,
                Some(Item::Node(node)) => is_word(node, word),
                None => false,
            });
            match (word, next) {
                (Some(index), _) => return Ok(Some(index)),
                (None, Some(Item::Node(_))) if slot => return Ok(Some(first_words.len())),
                _ => {}
            }
            let mut error = match next {
                Some(Item::Word(text, span)) => {
                    DecodeError::new(*span, format!("the word {}", code(text)), "")
                }
                Some(Item::Node(node)) => mismatch(node, ""),
                None => DecodeError::new(self.end.1, self.end.0, ""),
            };
            error.expected = expected.iter().map(|one| one.to_string()).collect();
            if optional {
                self.missed = Some(self.fail(error));
                return Ok(None);
            }
            if self.may_be_other_call() {
                return Err(self.is_other_call());
            }
            Err(self.fail(error))
        }

        /// Matches the word `text`: a name word of a call, or an element that is
        /// that word alone.
        pub fn word(&mut self, text: &str) -> Result<&mut Self, DecodeError> {
            self.word_span(text)?;
            Ok(self)
        }

        /// Like [`Sequence::word`], giving the word's span. `text` may be
        /// several words separated by spaces, from `WORDS "a b"`: they are
        /// matched in a row, and the span runs from the first to the last.
        pub fn word_span(&mut self, text: &str) -> Result<Span, DecodeError> {
            let mut span: Option<Span> = None;
            for word in text.split(' ') {
                let found = match self.items.get(self.index) {
                    Some(Item::Word(found, at)) if *found == word => *at,
                    Some(Item::Node(node)) if is_word(node, word) => node.span,
                    Some(Item::Node(_)) if self.may_be_other_call() => {
                        return Err(self.is_other_call());
                    }
                    _ => return Err(self.unexpected(&format!("the word {}", code(text)))),
                };
                self.index += 1;
                self.other_call = None;
                span = Some(span.map_or(found, |first| first.to(found)));
            }
            Ok(span.unwrap_or(Span::empty(0)))
        }

        /// Matches every name word in a row, at least one, whose text, the
        /// words joined by spaces, must pass `condition`.
        pub fn words(
            &mut self,
            condition: impl Fn(&str) -> bool,
            expected: &str,
        ) -> Result<Spanned<String>, DecodeError> {
            let words: Vec<(&str, Span)> = self.items[self.index..]
                .iter()
                .map_while(|item| match item {
                    Item::Word(text, span) => Some((*text, *span)),
                    Item::Node(_) => None,
                })
                .collect();
            let (Some((_, first)), Some((_, last))) = (words.first(), words.last()) else {
                if self.may_be_other_call() {
                    return Err(self.is_other_call());
                }
                return Err(self.unexpected(expected));
            };
            let span = first.to(*last);
            let text = words
                .iter()
                .map(|(text, _)| *text)
                .collect::<Vec<_>>()
                .join(" ");
            if !condition(&text) {
                let error = match self.other_call.is_some() {
                    true => self.is_other_call(),
                    false => {
                        let error =
                            DecodeError::new(span, format!("the words {}", code(&text)), expected);
                        self.fail(error)
                    }
                };
                return Err(error);
            }
            self.index += words.len();
            self.other_call = None;
            Ok(Spanned { value: text, span })
        }

        /// Matches one node. `expected` names it when nothing is there.
        pub fn one<T>(
            &mut self,
            decode: impl FnOnce(&'a Node) -> Result<T, DecodeError>,
            expected: &str,
        ) -> Result<T, DecodeError> {
            let node = match self.items.get(self.index) {
                Some(Item::Node(node)) => *node,
                Some(Item::Word(..)) if self.other_call.is_some() => {
                    return Err(self.is_other_call());
                }
                _ => return Err(self.unexpected(expected)),
            };
            match decode(node) {
                Ok(value) => {
                    self.index += 1;
                    Ok(value)
                }
                Err(error) => Err(self.fail(error)),
            }
        }

        /// Matches one node if it is there and fits.
        pub fn optional<T>(
            &mut self,
            decode: impl FnOnce(&'a Node) -> Result<T, DecodeError>,
        ) -> Option<T> {
            let Some(Item::Node(node)) = self.items.get(self.index) else {
                return None;
            };
            match decode(node) {
                Ok(value) => {
                    self.index += 1;
                    Some(value)
                }
                Err(error) => {
                    self.missed = Some(self.fail(error));
                    None
                }
            }
        }

        /// Matches nodes for as long as they fit.
        pub fn zero_or_more<T>(
            &mut self,
            decode: impl Fn(&'a Node) -> Result<T, DecodeError>,
        ) -> Vec<T> {
            let mut values = Vec::new();
            while let Some(value) = self.optional(&decode) {
                values.push(value);
            }
            values
        }

        /// Decodes every node left, each on its own. A node that does not fit is
        /// kept as its error, and the nodes after it still decode, so one
        /// mistake in a list does not hide the rest. A word stops it: in a call,
        /// a name word after the nodes is matched next.
        pub fn each<T>(
            &mut self,
            decode: impl Fn(&'a Node) -> Result<T, DecodeError>,
        ) -> Vec<Result<T, DecodeError>> {
            let mut values = Vec::new();
            while let Some(Item::Node(node)) = self.items.get(self.index) {
                values.push(decode(node));
                self.index += 1;
            }
            values
        }

        /// Matches one node, then more for as long as they fit.
        pub fn one_or_more<T>(
            &mut self,
            decode: impl Fn(&'a Node) -> Result<T, DecodeError>,
            expected: &str,
        ) -> Result<Vec<T>, DecodeError> {
            let mut values = vec![self.one(&decode, expected)?];
            values.extend(self.zero_or_more(decode));
            Ok(values)
        }

        /// Every node left, for an `ANY ORDER` to sort. A word stops it, as
        /// with [`Sequence::each`].
        pub fn rest(&mut self) -> Vec<&'a Node> {
            let mut nodes = Vec::new();
            while let Some(Item::Node(node)) = self.items.get(self.index) {
                nodes.push(*node);
                self.index += 1;
            }
            nodes
        }

        /// The value of an `ANY ORDER` element that must be there, or the error
        /// saying it is missing, at the end of the sequence.
        pub fn required<T>(&self, found: Option<T>, expected: &str) -> Result<T, DecodeError> {
            found.ok_or_else(|| DecodeError::new(self.end.1, self.end.0, expected))
        }

        /// The values of a `ONE OR MORE` element of an `ANY ORDER`, or the
        /// error saying there are none.
        pub fn at_least_one<T>(
            &self,
            found: Vec<T>,
            expected: &str,
        ) -> Result<Vec<T>, DecodeError> {
            match found.is_empty() {
                true => Err(DecodeError::new(self.end.1, self.end.0, expected)),
                false => Ok(found),
            }
        }

        /// Checks that nothing is left.
        pub fn finish(&mut self) -> Result<(), DecodeError> {
            if self.index == self.items.len() {
                return Ok(());
            }
            let end = self.end.0;
            Err(self.unexpected(end))
        }
    }

    /// One node of an `ANY ORDER`, tried against each element in turn.
    pub struct Attempts<'a> {
        node: &'a Node,
        /// Why the elements tried so far did not fit, merged.
        error: Option<DecodeError>,
    }

    impl<'a> Attempts<'a> {
        pub fn new(node: &'a Node) -> Self {
            Attempts { node, error: None }
        }

        /// The node decoded by `decode`, if it fits.
        pub fn attempt<T>(
            &mut self,
            decode: impl FnOnce(&'a Node) -> Result<T, DecodeError>,
        ) -> Option<T> {
            match decode(self.node) {
                Ok(value) => Some(value),
                Err(error) => {
                    self.error = Some(match self.error.take() {
                        Some(earlier) => earlier.merge(error),
                        None => error,
                    });
                    None
                }
            }
        }

        /// Why the node fits no element.
        pub fn error(self) -> DecodeError {
            let node = self.node;
            self.error
                .unwrap_or_else(|| DecodeError::new(node.span, describe(node), "nothing"))
        }
    }

    /// Keeps `value` as the one `label` of an `ANY ORDER`, or gives the error
    /// for a second one, keeping the first.
    pub fn once<T>(
        slot: &mut Option<T>,
        value: T,
        node: &Node,
        label: &str,
    ) -> Option<DecodeError> {
        if slot.is_some() {
            return Some(DecodeError::new(
                node.span,
                format!("a second `{label}`"),
                format!("one `{label}` at most"),
            ));
        }
        *slot = Some(value);
        None
    }

    fn is_word(node: &Node, expected: &str) -> bool {
        matches!(
            &node.kind,
            NodeKind::Call(call)
                if matches!(&call.name[..], [NamePart::Word { text, .. }] if text == expected)
        )
    }

    /// The word `text`, standing alone.
    pub fn word(node: &Node, text: &str) -> Result<Span, DecodeError> {
        match is_word(node, text) {
            true => Ok(node.span),
            false => Err(mismatch(node, &format!("the word {}", code(text)))),
        }
    }

    /// `text` quoted as code: `` `x` ``, or with two backticks around text
    /// that holds one, as the word `` ` ``.
    pub fn code(text: &str) -> String {
        match text.contains('`') {
            true => format!("`` {text} ``"),
            false => format!("`{text}`"),
        }
    }

    /// The node `_`.
    pub fn underscore(node: &Node) -> Result<Span, DecodeError> {
        match node.kind {
            NodeKind::Underscore => Ok(node.span),
            _ => Err(mismatch(node, "`_`")),
        }
    }

    /// Any node, as it is.
    pub fn any_node(node: &Node) -> Result<Node, DecodeError> {
        Ok(node.clone())
    }

    /// Any word standing alone whose text passes `condition`.
    pub fn any_word(
        node: &Node,
        condition: impl Fn(&str) -> bool,
        expected: &str,
    ) -> Result<Spanned<String>, DecodeError> {
        let text = match &node.kind {
            NodeKind::Call(call) => match &call.name[..] {
                [NamePart::Word { text, .. }] => Some(text),
                _ => None,
            },
            _ => None,
        };
        match text {
            Some(text) if condition(text) => Ok(Spanned {
                value: text.clone(),
                span: node.span,
            }),
            _ => Err(mismatch(node, expected)),
        }
    }

    /// A string whose value passes `condition`.
    pub fn string(
        node: &Node,
        condition: impl Fn(&str) -> bool,
        expected: &str,
    ) -> Result<Spanned<StringLiteral>, DecodeError> {
        match &node.kind {
            NodeKind::String(literal) if condition(&literal.value) => Ok(Spanned {
                value: literal.clone(),
                span: node.span,
            }),
            _ => Err(mismatch(node, expected)),
        }
    }

    /// A `#` line string whose value passes `condition`. A quoted or raw string
    /// is named by its kind, since its kind is what is wrong.
    pub fn line_string(
        node: &Node,
        condition: impl Fn(&str) -> bool,
        expected: &str,
    ) -> Result<Spanned<StringLiteral>, DecodeError> {
        match &node.kind {
            NodeKind::String(literal) if literal.kind != StringKind::Line => {
                let kind = match literal.kind {
                    StringKind::Raw => "raw",
                    _ => "quoted",
                };
                Err(DecodeError::new(
                    node.span,
                    format!("the {kind} string {}", string_value(literal)),
                    expected,
                ))
            }
            _ => string(node, condition, expected),
        }
    }

    /// The value of a number.
    #[derive(Clone, Copy, Debug, PartialEq)]
    pub enum NumberValue {
        Integer(i128),
        Float(f64),
    }

    impl NumberValue {
        pub fn as_float(self) -> f64 {
            match self {
                NumberValue::Integer(value) => value as f64,
                NumberValue::Float(value) => value,
            }
        }
    }

    /// Reads a number's text: decimal with an optional fraction and exponent, or
    /// `0x`, `0b` or `0o` and digits, with `_` between digits and an optional
    /// leading `-`. A value with no fractional part is an integer however it is
    /// written, so `1e3` and `1000.0` are the integer 1000.
    pub fn number_value(text: &str) -> NumberValue {
        let (negative, digits) = match text.strip_prefix('-') {
            Some(digits) => (true, digits),
            None => (false, text),
        };
        let digits: String = digits.chars().filter(|c| *c != '_').collect();
        let radix = match digits.as_bytes() {
            [b'0', b'x' | b'X', ..] => 16,
            [b'0', b'b' | b'B', ..] => 2,
            [b'0', b'o' | b'O', ..] => 8,
            _ => 10,
        };
        let value = if radix != 10 {
            match i128::from_str_radix(&digits[2..], radix) {
                Ok(value) => NumberValue::Integer(value),
                Err(_) => NumberValue::Float(digits[2..].chars().fold(0.0, |value, digit| {
                    value * f64::from(radix) + f64::from(digit.to_digit(radix).unwrap_or(0))
                })),
            }
        } else if let Ok(value) = digits.parse::<i128>() {
            NumberValue::Integer(value)
        } else {
            let value: f64 = digits.parse().unwrap_or(f64::NAN);
            if value.fract() == 0.0 && value.abs() < 1e18 {
                NumberValue::Integer(value as i128)
            } else {
                NumberValue::Float(value)
            }
        };
        match (negative, value) {
            (false, value) => value,
            (true, NumberValue::Integer(value)) => NumberValue::Integer(-value),
            (true, NumberValue::Float(value)) => NumberValue::Float(-value),
        }
    }

    /// The value of a number node, or when `signed` also of `+ n` and `- n`.
    fn number_of(node: &Node, signed: bool) -> Option<NumberValue> {
        match &node.kind {
            NodeKind::Number(text) => Some(number_value(text)),
            NodeKind::Call(call) if signed => match (&call.name[..], &call.arguments[..]) {
                ([NamePart::Word { text, .. }, NamePart::Slot], [number]) => {
                    let NodeKind::Number(digits) = &number.kind else {
                        return None;
                    };
                    match (text.as_str(), number_value(digits)) {
                        ("+", value) => Some(value),
                        ("-", NumberValue::Integer(value)) => Some(NumberValue::Integer(-value)),
                        ("-", NumberValue::Float(value)) => Some(NumberValue::Float(-value)),
                        _ => None,
                    }
                }
                _ => None,
            },
            _ => None,
        }
    }

    /// An integer from `minimum` to `maximum`. When `signed`, a sign written
    /// apart from the number, as in `+ 4` or `- 4`, is taken too.
    pub fn integer<T: TryFrom<i128>>(
        node: &Node,
        minimum: i128,
        maximum: i128,
        signed: bool,
        expected: &str,
    ) -> Result<Spanned<T>, DecodeError> {
        let value = match number_of(node, signed) {
            Some(NumberValue::Integer(value)) if (minimum..=maximum).contains(&value) => {
                T::try_from(value).ok()
            }
            _ => None,
        };
        match value {
            Some(value) => Ok(Spanned {
                value,
                span: node.span,
            }),
            None => Err(mismatch(node, expected)),
        }
    }

    /// A number from `minimum` to `maximum`, taking `+ n` and `- n` when
    /// `signed`.
    pub fn float(
        node: &Node,
        minimum: f64,
        maximum: f64,
        signed: bool,
        expected: &str,
    ) -> Result<Spanned<f64>, DecodeError> {
        if let Some(value) = number_of(node, signed) {
            let value = value.as_float();
            if minimum <= value && value <= maximum {
                return Ok(Spanned {
                    value,
                    span: node.span,
                });
            }
        }
        Err(mismatch(node, expected))
    }

    /// The `FORMAT` of one `ANYFIX CALL` in the grammar: a call whose name words
    /// include `words`, in order, may break its line before each of
    /// `break_before`.
    #[derive(Clone, Copy, Debug)]
    pub struct LayoutRule {
        pub words: &'static [&'static str],
        pub break_before: &'static [&'static str],
    }

    /// Formats `source` with anyx, laying out each call by the rule of `rules`
    /// that names most of its words. A call that only looks like one of the
    /// grammar's gets its layout too, which changes nothing but whitespace.
    pub fn format(source: &str, rules: &[LayoutRule]) -> Result<String, Vec<anyx::Error>> {
        let parsed = anyx::parse(source);
        let mut layout = anyx::Layout::new();
        if parsed.errors.is_empty() {
            mark_breaks(&parsed.syntax.nodes(), rules, &mut layout);
        }
        anyx::format_with(source, &layout)
    }

    fn mark_breaks(nodes: &[Node], rules: &[LayoutRule], layout: &mut anyx::Layout) {
        for node in nodes {
            match &node.kind {
                NodeKind::Call(call) => {
                    let words: Vec<(&str, Span)> = call
                        .name
                        .iter()
                        .filter_map(|part| match part {
                            NamePart::Word { text, span } => Some((text.as_str(), *span)),
                            NamePart::Slot => None,
                        })
                        .collect();
                    let rule = rules
                        .iter()
                        .filter(|rule| {
                            let mut remaining = words.iter();
                            rule.words
                                .iter()
                                .all(|word| remaining.any(|(text, _)| text == word))
                        })
                        .max_by_key(|rule| rule.words.len());
                    if let Some(rule) = rule {
                        words
                            .iter()
                            .filter(|(text, _)| rule.break_before.contains(text))
                            .for_each(|(_, span)| layout.break_before(span.start));
                    }
                    mark_breaks(&call.arguments, rules, layout);
                }
                NodeKind::Parens(nodes) | NodeKind::Brackets(nodes) | NodeKind::Braces(nodes) => {
                    mark_breaks(nodes, rules, layout)
                }
                _ => {}
            }
        }
    }

    /// A number classified by its spelling, retaining its text exactly. A based
    /// integer's hexadecimal `e` is a digit, never an exponent.
    pub fn number_literal(
        node: &Node,
        float: bool,
        expected: &str,
    ) -> Result<Spanned<String>, DecodeError> {
        let NodeKind::Number(text) = &node.kind else {
            return Err(mismatch(node, expected));
        };
        let digits = text.strip_prefix('-').unwrap_or(text);
        let based = ["0x", "0X", "0b", "0B", "0o", "0O"]
            .iter()
            .any(|prefix| digits.starts_with(prefix));
        let is_float = !based && digits.contains(['.', 'e', 'E']);
        if is_float != float {
            return Err(mismatch(node, expected));
        }
        Ok(Spanned {
            value: text.clone(),
            span: node.span,
        })
    }
}
